package lifecycleops

import (
	"fmt"
	"os"
	"path/filepath"

	"github.com/stricttools/strictspec/go/lifecycle"

	"github.com/stricttools/rlsbl/internal/declarations"
	"github.com/stricttools/rlsbl/internal/git"
	"github.com/stricttools/rlsbl/internal/workspace"
)

// InitMinimalRecord writes the minimal lifecycle-and-license record (only
// its format version, with the ownership manifest naming strictspec) into a
// repository rlsbl does not manage, and commits both with the Autogenerated
// trailer. With no license period the repository is public. It reads no
// declarations; a repository holding them, or an old-layout directory, is
// rlsbl's and is refused, and so is a repository that already holds a
// record.
func (inv Invocation) InitMinimalRecord(dir string) error {
	root, err := declarations.FindRepositoryRoot(dir)
	if err != nil {
		return err
	}
	repo, err := git.Open(inv.E, root)
	if err != nil {
		return err
	}
	if _, err := os.Lstat(filepath.Join(root, filepath.FromSlash(declarations.ReleasablesFile))); err == nil {
		return fmt.Errorf("rlsbl manages this repository (it holds %s), so its record is written by the transition commands, beginning with `rlsbl transition license`; nothing was written", declarations.ReleasablesFile)
	} else if !os.IsNotExist(err) {
		return err
	}
	tracked, err := repo.TrackedFiles()
	if err != nil {
		return err
	}
	old, err := workspace.OldLayoutDirectory(root, tracked)
	if err != nil {
		return err
	}
	if old != "" {
		return fmt.Errorf("rlsbl manages this repository (it holds %s/ of the old layout), so its record is written by `rlsbl migrate records`, which converts the old layout; nothing was written", old)
	}
	if _, err := os.Lstat(filepath.Join(root, filepath.FromSlash(lifecycle.RecordFile))); err == nil {
		return fmt.Errorf("%s already exists; the minimal record is written only where there is none, and nothing was written", lifecycle.RecordFile)
	} else if !os.IsNotExist(err) {
		return err
	}
	rec, err := lifecycle.Load(root)
	if err != nil {
		return err
	}
	on := inv.Now()
	if err := rec.Validate(on, nil); err != nil {
		return err
	}
	return inv.write(root, repo, rec, on, "transition: write a minimal lifecycle-and-license record",
		outcome{"Wrote the minimal record " + lifecycle.RecordFile + ": the repository is public.", "Would write the minimal record " + lifecycle.RecordFile + ": the repository is public."})
}
